              <Box key={`${key}-value-${i}`}>
                <Text>
                  {percentUsed === undefined
                    ? formatUsd(row.cost)
                    : formatPercent(total > 0 ? (percentUsed * row.cost) / total : 0)}
                </Text>
              </Box>
            ))}
          </Box>
        </Box>
