          <Box key="cache" flexDirection="column">
            <Text>{`Hit rate ${formatPercent(cache.hitRate * 100)} over the last requests`}</Text>
            <Text color={cache.reReads > 0 ? 'warning' : undefined} dimColor={cache.reReads === 0}>
